      moveFocus(list, null, disableListWrap, previousItem);
    }

    if (onKeyDown) {
      onKeyDown(event);
    }
  };

  const handleOwnRef = React.useCallback(instance => {
    // #StrictMode ready
    listRef.current = ReactDOM.findDOMNode(instance);
